"use client";

import { useMemo, type ReactNode } from "react";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
} from "@/registry/default/components/data-grid/data-grid";
import { useDataGridState } from "@/registry/default/components/data-grid-history/data-grid-history";
import {
  useDataGridPinnedRows,
  aggregateRow,
} from "@/registry/default/components/data-grid-pinned-rows/data-grid-pinned-rows";
import { DataGridToolbar, DataGridFilterMenu } from "@/registry/default/components/data-grid-toolbar/data-grid-toolbar";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 90, flex: 1 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 100, flex: 2 },
  { id: "age", header: "Age", accessorKey: "age", type: "number", width: 55, flex: 1 },
  {
    id: "role",
    header: "Role",
    accessorKey: "role",
    type: "select",
    options: {
      choices: [
        "Admin",
        "User",
        "Editor",
        "Viewer",
        "Manager",
      ],
    },
    width: 80,
    flex: 1,
    filterable: true,
  },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 55, flex: 1 },
] as const);

const AVERAGES = aggregateRow<DemoRow>({ age: "avg", score: "avg" }, { cells: { id: "averages", role: "Average" } });
const TOTALS = aggregateRow<DemoRow>(
  { name: (_values, rows) => `${rows.length} rows`, age: "sum", score: "sum" },
  { cells: { id: "totals", role: "Total" } },
);

/**
 * Pinned rows (`data-grid-pinned-rows` add-on): an averages row pinned under the header and a
 * totals row pinned at the viewport's bottom edge, both declared with `aggregateRow` —
 * filter-aware, so the bands only reflect the rows the filter/sort view actually shows. Filter the
 * Role column via the toolbar to watch both bands recompute over just the filtered rows.
 * Edit a Score or Age cell to watch both bands update too.
 */
export default function DataGridPinnedRowsDemo(): ReactNode {
  const grid = useDataGridState(generateDemoRows(30), { getRowId: (row) => row.id });
  const { plugin: pinnedRowsPlugin } = useDataGridPinnedRows({ topRows: [AVERAGES], bottomRows: [TOTALS] });
  const plugins = useMemo(() => [...grid.plugins, pinnedRowsPlugin], [grid.plugins, pinnedRowsPlugin]);

  return (
    <div className="w-full flex flex-col gap-3">
      <p className="text-sm text-muted-foreground">
        Filter the Role column via the toolbar: the pinned Average and Total rows recompute over only
        the rows the filter leaves visible, not the full dataset.
      </p>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider {...grid} columns={columns} plugins={plugins}>
          <DataGridToolbar>
            <DataGridFilterMenu />
          </DataGridToolbar>
          <DataGridRoot className="min-h-0 flex-1 rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
